// Checks your settings and turns them into the Google Trends Actor's input.
const s = $('Your settings').first().json;
const keywords = [...new Set(String(s.keywords || '').split(',').map(k => k.trim()).filter(Boolean))];
if (!keywords.length) throw new Error('Add at least one keyword in "Your settings".');
if (keywords.length > 50) throw new Error('Use at most 50 keywords per run, so the Actor finishes within 5 minutes.');
if (!['now 7-d', 'today 1-m', 'today 3-m', 'today 12-m'].includes(s.timeRange))
  throw new Error('timeRange must be one of: now 7-d, today 1-m, today 3-m, today 12-m.');

const components = ['relatedQueries'];
if (s.includeTopics) components.push('relatedTopics');
return [{ json: { actorInput: {
  keywords,
  preset: 'custom',
  components,              // only the parts this workflow uses, so you only pay for those
  geo: s.country || '',    // empty = worldwide
  timeRange: s.timeRange,
  maxTopicsWaitMinutes: 3, // keeps runs short; topics Google holds back longer are skipped (and not charged)
} } }];

// One item per rising search or topic, exactly as Google Trends reported it. No decisions here.
// Google marks very fast growth as "Breakout" (more than +5,000%), so it gets 5000.
const growthNumber = g => /breakout/i.test(g || '') ? 5000 : (parseInt(String(g || '').replace(/[^0-9]/g, ''), 10) || 0);
const rows = [];
for (const { json: k } of $input.all()) {
  if (!['complete', 'partial'].includes(k.status)) continue; // e.g. low volume: Google has no data for it (free)
  for (const q of k.relatedQueries?.rising || [])
    rows.push({ seed: k.keyword, kind: 'search', text: q.query, topicType: '', growth: q.growth || '', growthNumber: growthNumber(q.growth) });
  for (const t of k.relatedTopics?.rising || [])
    rows.push({ seed: k.keyword, kind: 'topic', text: t.title, topicType: t.type || '', growth: t.growth || '', growthNumber: growthNumber(t.growth) });
}
// an empty week still has to reach "Nothing new this week", and n8n stops a branch that outputs no items
return rows.length ? rows.map(json => ({ json })) : [{ json: { noRisingSearches: true } }];

// Turns raw rising searches into a short, ranked list worth writing about.
//  1. Junk out. Google Trends data now carries bot and AI-agent traffic: prompt-like searches
//     ("explain what X is and its main benefits") and generic Breakouts ("how to make sushi") under unrelated keywords.
//  2. Relevance. With AI on, the AI judges it later. Without AI, a search must share a real word with its keyword or niche.
//  3. Variants merged: "trader joe's retinol" and "trader joes retinol" become one idea.
//  4. Ranked by growth, boosted when it rises under several of your keywords or as both a search and a topic.
//  5. Skips what you got in the last 8 weeks, flags what's new since the last run, spreads ideas across keywords.
const s = $('Your settings').first().json;
const useAI = s.useAI === true;
const limit = Math.max(1, Number(s.ideasPerRun) || 10);
const candidates = useAI ? Math.min(limit * 3, 40) : limit; // the AI gets extra so it can drop the off-topic ones

// ---- tuning (safe to change) ----
const STOP = new Set(['for', 'the', 'and', 'with', 'from', 'that', 'this', 'your', 'you', 'how', 'what', 'when', 'why',
  'who', 'which', 'can', 'does', 'best', 'top', 'near', 'are', 'was', 'use', 'using', 'new', 'free', 'good', 'get', 'not',
  'all', 'about', 'into', 'like', 'more', 'most', 'make', 'way', 'ways', 'vs', 'review', 'reviews', 'usa', 'online']);
const PROMPT_START = /^(explain|describe|write|list|give me|tell me|summarize|summarise|compare|create|generate|provide|act as)\b/i;
const MAX_WORDS = 9;           // longer "searches" read like prompts, not people
const JUNK_UNDER_KEYWORDS = 3; // the same unrelated search under this many of your keywords = bot junk
const BOOST_PER_EXTRA_KEYWORD = 0.5, BOOST_SEARCH_AND_TOPIC = 0.2, NOT_NEW_FACTOR = 0.8;
const REMEMBER_WEEKS = 8;

const norm = t => String(t).toLowerCase().replace(/['’]/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const words = t => norm(t).split(' ').filter(w => w.length > 2 && !STOP.has(w));
const stems = t => new Set(words(t).map(w => w.slice(0, 5)));
const shares = (a, b) => [...a].some(x => b.has(x));
const nicheStems = stems(`${s.niche || ''} ${s.audience || ''}`);

const all = $input.all().map(i => i.json).filter(r => r.text); // drops the "no rising searches" marker
const seeds = [...new Set($('Google Trends').all().map(i => i.json.keyword))];
const seedsWithData = new Set(all.map(r => r.seed));
const stats = { risingFound: all.length, junk: 0, offTopic: 0, merged: 0, alreadySent: 0,
  keywordsWithoutData: seeds.filter(k => !seedsWithData.has(k)) };

// 1 + 2: junk and relevance
const under = {};
for (const r of all) (under[norm(r.text)] ??= new Set()).add(r.seed);
const kept = all.filter(r => {
  r.related = shares(stems(r.text), new Set([...stems(r.seed), ...nicheStems]));
  const promptLike = r.kind === 'search' && (PROMPT_START.test(r.text) || norm(r.text).split(' ').length >= MAX_WORDS);
  const repeated = under[norm(r.text)].size >= JUNK_UNDER_KEYWORDS && !r.related;
  if (promptLike || repeated) { stats.junk++; return false; }
  if (!useAI && !r.related) { stats.offTopic++; return false; }
  return true;
});

// 3: merge variants: the same words once filler ("usa", "reviews", "best"...) and plural "s" are ignored
const sig = r => [...new Set(words(r.text).map(w => w.replace(/(?<=..)s$/, '')))].sort().join(' ') || norm(r.text);
const groups = [];
for (const r of kept.sort((a, b) => b.growthNumber - a.growthNumber)) {
  const g = groups.find(g => g.sig === sig(r));
  if (g) {
    stats.merged++;
    g.seeds.add(r.seed); g.kinds.add(r.kind);
    if (norm(r.text) !== norm(g.text)) g.variants.add(r.text);
    if (r.topicType && !g.topicType) g.topicType = r.topicType;
    g.related ||= r.related;
  } else {
    groups.push({ sig: sig(r), wordSet: new Set(sig(r).split(' ')), text: r.text, growth: r.growth,
      growthNumber: r.growthNumber, topicType: r.topicType, related: r.related,
      seeds: new Set([r.seed]), kinds: new Set([r.kind]), variants: new Set() });
  }
}
// a topic that names the same thing as a search (all its 3+ words are in the search) joins that search
for (const t of groups.filter(g => g.kinds.size === 1 && g.kinds.has('topic') && g.wordSet.size >= 3)) {
  const q = groups.find(g => g !== t && g.kinds.has('search') && [...t.seeds].some(k => g.seeds.has(k))
    && [...t.wordSet].every(w => g.wordSet.has(w)));
  if (!q) continue;
  stats.merged++;
  q.kinds.add('topic'); q.variants.add(t.text); q.topicType ||= t.topicType;
  q.growthNumber = Math.max(q.growthNumber, t.growthNumber);
  t.mergedInto = q;
}
for (let i = groups.length - 1; i >= 0; i--) if (groups[i].mergedInto) groups.splice(i, 1);

// 4 + 5: memory, score, spread
const memory = $getWorkflowStaticData('global');
memory.sent ??= {};
const now = Date.now();
for (const [k, t] of Object.entries(memory.sent)) if (now - t > REMEMBER_WEEKS * 7 * 86400e3) delete memory.sent[k];
const lastRun = new Set(memory.lastRun || []);
memory.lastRun = groups.map(g => g.sig);

const scored = groups
  .filter(g => { if (memory.sent[g.sig]) { stats.alreadySent++; return false; } return true; })
  .map(g => {
    const isNew = !lastRun.has(g.sig);
    const score = g.growthNumber * (1 + BOOST_PER_EXTRA_KEYWORD * (g.seeds.size - 1))
      * (g.kinds.size > 1 ? 1 + BOOST_SEARCH_AND_TOPIC : 1) * (isNew ? 1 : NOT_NEW_FACTOR);
    return { ...g, isNew, score };
  })
  .sort((a, b) => b.score - a.score);

// With AI, searches that share no word with your keywords still get a chance (new brands and ingredients often
// don't), but only up to a third of the list, after the related ones, so bot junk can't crowd out real ideas.
const perSeed = Math.max(2, Math.ceil(candidates / Math.max(1, seedsWithData.size)));
const used = {};
const picked = [];
const take = (list, max) => {
  for (const g of list) {
    if (picked.length >= max) return;
    if (picked.includes(g)) continue;
    const main = [...g.seeds][0];
    if ((used[main] || 0) < perSeed) { used[main] = (used[main] || 0) + 1; picked.push(g); }
  }
};
const related = scored.filter(g => g.related), unrelated = scored.filter(g => !g.related);
take(related, useAI ? candidates - Math.ceil(candidates / 3) : candidates);
take(unrelated, candidates);
take(related, candidates);

if (!picked.length) return [{ json: { nothingNew: true, stats } }];
const geo = encodeURIComponent(s.country || ''), date = encodeURIComponent(s.timeRange);
return picked.map((g, i) => ({ json: {
  n: i + 1,
  key: g.sig,
  text: g.text,
  variants: [...g.variants],
  kind: [...g.kinds].sort().join(' + '),  // "search", "topic" or "search + topic"
  topicType: g.topicType,
  growth: g.growth,
  seeds: [...g.seeds],
  isNew: g.isNew,
  googleTrends: `https://trends.google.com/trends/explore?q=${encodeURIComponent(g.text)}&geo=${geo}&date=${date}`,
  stats,
} }));

// Joins the AI's ideas back to their searches, keeps the relevant ones, best first.
const s = $('Your settings').first().json;
const minRelevance = Number(s.minRelevance) || 6;
const limit = Math.max(1, Number(s.ideasPerRun) || 10);
const byN = Object.fromEntries((($input.first().json.output || {}).ideas || []).map(i => [Number(i.n), i]));
const all = $('Clean and rank').all().map(({ json: c }) => ({ c, i: byN[c.n] }));
const relevant = all.filter(({ i }) => i && Number(i.relevance) >= minRelevance && i.title);
const aiDropped = all.length - relevant.length; // judged off-topic by the AI (shown in the summary)
return relevant
  .sort((a, b) => b.i.relevance - a.i.relevance || a.c.n - b.c.n)
  .slice(0, limit)
  .map(({ c, i }) => ({ json: { ...c, idea: i.title, angle: i.angle || '', hook: i.hook || '', format: i.format || '',
    whyRising: i.whyRising || '', checkBeforePublishing: i.checkBeforePublishing || [], relevance: Number(i.relevance),
    aiDropped } }));

// Without AI: a sensible idea per search, based on what kind of search it is.
const cap = t => t.charAt(0).toUpperCase() + t.slice(1);
return $input.all().map(({ json: c }) => {
  const t = c.text, low = t.toLowerCase();
  let idea, format;
  if (/^(how|what|why|when|which|who|can|is|are|does|do|should|will)\b/.test(low)) {
    idea = `${cap(t)}?`; format = 'blog post that answers the question';
  } else if (/\bvs\.?\b|\bversus\b|\bor\b/.test(low)) {
    idea = `${cap(t)}: which one should you choose?`; format = 'comparison';
  } else if (/\breviews?\b/.test(low) || /brand|product|cosmetic|moisturizer|serum|cream|sunscreen/i.test(c.topicType)) {
    idea = `${cap(t.replace(/\s*reviews?\s*$/i, ''))}: honest review`; format = 'review or short video';
  } else if (/near me|open now/.test(low)) {
    idea = `${cap(t)}: a local guide`; format = 'local page';
  } else {
    idea = `${cap(t)}: why people are searching for it now`; format = 'short video or carousel';
  }
  const more = c.variants.length ? ` People also search "${c.variants.join('", "')}".` : '';
  return { json: { ...c, idea, format,
    angle: `Searches for "${t}" are up ${c.growth} around ${c.seeds.map(k => `"${k}"`).join(', ')}.${more} Cover what changed and what people want to know.`,
    hook: /\?$/.test(idea) ? `${idea} Here is the short answer.` : `Searches for "${t}" just jumped ${c.growth}.`,
    whyRising: '', checkBeforePublishing: ['Open the Google Trends link to see what is driving the rise'], relevance: '' } };
});

// One row per idea, in a fixed set of columns any output can use, and remembers what was sent.
const memory = $getWorkflowStaticData('global');
memory.sent ??= {};
const today = new Date().toISOString().slice(0, 10);
return $input.all().map(({ json: c }) => {
  memory.sent[c.key] = Date.now();
  return { json: {
    date: today,
    status: 'to review',
    idea: c.idea,
    angle: c.angle,
    hook: c.hook,
    format: c.format,
    whyRising: c.whyRising,
    checkBeforePublishing: (c.checkBeforePublishing || []).join('; '),
    risingSearch: c.text,
    alsoSearchedAs: c.variants.join('; '),
    type: c.kind + (c.topicType ? ` (${c.topicType})` : ''),
    growth: c.growth,
    newThisWeek: c.isNew ? 'yes' : 'no',
    yourKeywords: c.seeds.join(', '),
    relevance: c.relevance,
    googleTrends: c.googleTrends,
  } };
});

// A short message for Slack or Telegram.
const rows = $input.all().map(i => i.json);
const st = $('Clean and rank').first().json.stats;
const aiDropped = $('Your settings').first().json.useAI ? ($('Match ideas to searches').first()?.json.aiDropped || 0) : 0;
const top = rows.slice(0, 5).map((r, n) => `${n + 1}. ${r.idea}\n   "${r.risingSearch}" ${r.growth}${r.newThisWeek === 'yes' ? ', new' : ''}`).join('\n');
const text = `${rows.length} content ideas from what's rising in your niche this week:\n\n${top}\n\n`
  + `From ${st.risingFound} rising searches: ${st.junk} junk and ${st.offTopic + aiDropped} off-topic removed, `
  + `${st.merged} variants merged, ${st.alreadySent} already sent.`;
return [{ json: { text } }];

// Sent instead of ideas when nothing new is rising, so a quiet week doesn't look like a broken workflow.
const st = $input.first().json.stats;
const noData = st.keywordsWithoutData.length ? ` Google has no data for: ${st.keywordsWithoutData.join(', ')}.` : '';
const detail = st.risingFound
  ? ` Of ${st.risingFound} rising searches, ${st.junk + st.offTopic} were junk or off-topic and ${st.alreadySent} were already sent to you.`
  : ' Google shows no rising searches for your keywords in this period.';
return [{ json: { text: `Nothing new is rising in your niche this week.${detail}${noData}` } }];
